const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const roi = ee.Geometry.Polygon([[[-6.1, 15.8], [-6.1, 13.0], [-3.0, 13.0], [-3.0, 15.8], [-6.1, 15.8]]], null, false);
    const periods = {
      may: { start: ee.Date('2022-05-01'), end: ee.Date('2022-06-01') },
      nov: { start: ee.Date('2022-11-01'), end: ee.Date('2022-12-01') }
    };
    const scale = 1000;
    const maxPixels = 1e9;
    const ndviThreshold = 0.3;

    // Helper to promisify getInfo/evaluate
    const getInfo = (obj) => new Promise((resolve, reject) => {
      obj.getInfo((v) => resolve(v), (e) => reject(e));
    });

    // 2. Data Acquisition helpers
    function maskS2(img) {
      const qa = img.select('QA60');
      const cloudBitMask = ee.Number(1).leftShift(10);
      const cirrusBitMask = ee.Number(1).leftShift(11);
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return img.updateMask(mask);
    }
    function s2NDVIcol(start, end) {
      const col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(roi)
        .filterDate(start, end)
        .filter(ee.Filter.lte('CLOUDY_PIXEL_PERCENTAGE', 80))
        .map(maskS2)
        .map(img => img.addBands(img.normalizedDifference(['B8', 'B4']).rename('NDVI')).select(['NDVI']));
      return col;
    }
    function scaleL2(img) {
      const optical = ['SR_B2','SR_B3','SR_B4','SR_B5','SR_B6','SR_B7'];
      const scaled = img.select(optical).multiply(2.75e-5).add(-0.2);
      return img.addBands(scaled, null, true);
    }
    function maskLandsatL2(img) {
      const qa = img.select('QA_PIXEL');
      const cloudShadowBit = 1 << 3;
      const snowBit = 1 << 4;
      const cloudBit = 1 << 5;
      const mask = qa.bitwiseAnd(cloudShadowBit).eq(0)
        .and(qa.bitwiseAnd(snowBit).eq(0))
        .and(qa.bitwiseAnd(cloudBit).eq(0));
      return img.updateMask(mask);
    }
    function landsatNDVIcol(start, end) {
      const l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterBounds(roi).filterDate(start, end);
      const l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterBounds(roi).filterDate(start, end);
      const merged = l8.merge(l9)
        .map(scaleL2)
        .map(maskLandsatL2)
        .map(img => img.addBands(img.normalizedDifference(['SR_B5','SR_B4']).rename('NDVI')).select(['NDVI']));
      return merged;
    }
    async function chooseDataset(start, end, label) {
      let col = s2NDVIcol(start, end);
      let countS2 = await getInfo(col.size());
      if (countS2 > 0) {
        return { col, dataset: 'S2', images: countS2, window: 'default' };
      }
      // fallback to Landsat 8/9
      col = landsatNDVIcol(start, end);
      let countL = await getInfo(col.size());
      if (countL > 0) {
        return { col, dataset: 'L8/9', images: countL, window: 'default' };
      }
      // widen window ±15 days
      const wstart = ee.Date(start).advance(-15, 'day');
      const wend = ee.Date(end).advance(15, 'day');
      col = s2NDVIcol(wstart, wend);
      countS2 = await getInfo(col.size());
      if (countS2 > 0) {
        return { col, dataset: 'S2', images: countS2, window: '±15d' };
      }
      col = landsatNDVIcol(wstart, wend);
      countL = await getInfo(col.size());
      if (countL > 0) {
        return { col, dataset: 'L8/9', images: countL, window: '±15d' };
      }
      return { col: null, dataset: 'None', images: 0, window: 'none' };
    }

    async function computeStats(selection, label) {
      if (!selection.col) {
        return { label, dataset: selection.dataset, images: 0, valid: 0, total: 0, cloudPct: null, vegFrac: null, window: selection.window };
      }
      const ndviMed = selection.col.median().select('NDVI');
      const ones = ee.Image.constant(1).rename('ones');
      const total = await getInfo(ones.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: scale,
        maxPixels: maxPixels
      }).get('ones'));
      const valid = await getInfo(ndviMed.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: scale,
        maxPixels: maxPixels
      }).get('NDVI'));
      if (total == null || valid == null) {
        return { label, dataset: selection.dataset, images: selection.images, valid: 0, total: 0, cloudPct: null, vegFrac: null, window: selection.window };
      }
      if (valid === 0) {
        const cloudPct = total > 0 ? (1 - 0 / total) * 100 : null;
        return { label, dataset: selection.dataset, images: selection.images, valid, total, cloudPct, vegFrac: null, window: selection.window };
      }
      const veg = ndviMed.gt(ndviThreshold).rename('veg');
      const vegCount = await getInfo(veg.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: roi,
        scale: scale,
        maxPixels: maxPixels
      }).get('veg'));
      const vegFrac = (vegCount == null || valid === 0) ? null : (vegCount / valid);
      const cloudPct = total > 0 ? (1 - valid / total) * 100 : null;
      return { label, dataset: selection.dataset, images: selection.images, valid, total, cloudPct, vegFrac, window: selection.window };
    }

    // 3. Processing
    const maySel = await chooseDataset(periods.may.start, periods.may.end, 'May 2022');
    const novSel = await chooseDataset(periods.nov.start, periods.nov.end, 'Nov 2022');

    if (maySel.images === 0 || novSel.images === 0) {
      if (maySel.images === 0) console.log('May 2022: Images: 0');
      if (novSel.images === 0) console.log('Nov 2022: Images: 0');
      console.log('C1');
      return;
    }

    const mayStats = await computeStats(maySel, 'May 2022');
    const novStats = await computeStats(novSel, 'Nov 2022');

    // 4. Validation for C2/C3
    const anyNoValid = (mayStats.valid === 0) || (novStats.valid === 0);
    if (anyNoValid) {
      console.log(`May 2022 - Dataset=${mayStats.dataset} (win=${mayStats.window}) images=${mayStats.images} | valid=${mayStats.valid} | total=${mayStats.total} | cloud%=${mayStats.cloudPct !== null ? mayStats.cloudPct.toFixed(1) : 'NA'} | vegFrac=${mayStats.vegFrac !== null ? mayStats.vegFrac.toFixed(3) : 'NA'}`);
      console.log(`Nov 2022 - Dataset=${novStats.dataset} (win=${novStats.window}) images=${novStats.images} | valid=${novStats.valid} | total=${novStats.total} | cloud%=${novStats.cloudPct !== null ? novStats.cloudPct.toFixed(1) : 'NA'} | vegFrac=${novStats.vegFrac !== null ? novStats.vegFrac.toFixed(3) : 'NA'}`);
      console.log('C2');
      return;
    }
    const invalidMay = (mayStats.vegFrac == null) || !isFinite(mayStats.vegFrac) || mayStats.vegFrac < 0 || mayStats.vegFrac > 1;
    const invalidNov = (novStats.vegFrac == null) || !isFinite(novStats.vegFrac) || novStats.vegFrac < 0 || novStats.vegFrac > 1;
    if (invalidMay || invalidNov) {
      console.log('C3');
      return;
    }

    // 5. Output concise evidence
    console.log(`May 2022 - Dataset=${mayStats.dataset} (win=${mayStats.window}) images=${mayStats.images} | valid=${mayStats.valid} | total=${mayStats.total} | cloud%=${mayStats.cloudPct.toFixed(1)} | vegFrac=${mayStats.vegFrac.toFixed(3)}`);
    console.log(`Nov 2022 - Dataset=${novStats.dataset} (win=${novStats.window}) images=${novStats.images} | valid=${novStats.valid} | total=${novStats.total} | cloud%=${novStats.cloudPct.toFixed(1)} | vegFrac=${novStats.vegFrac.toFixed(3)}`);
    const diff = novStats.vegFrac - mayStats.vegFrac;
    console.log(`Diff (Nov-May) vegFrac = ${diff >= 0 ? '+' : ''}${diff.toFixed(3)}`);

    // Final Answer
    if (!isFinite(diff)) {
      console.log('C3');
    } else if (diff > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.error(String(err).slice(0, 300));
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
